sys_script_include.script:
var FutureCoursesFilter = Class.create();
FutureCoursesFilter.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    initialize: function() {},

    getAvailableDates: function() {
        var courseId = this.getParameter('sysparm_course'); // ID do curso selecionado
        // var today = new GlideDate(); // Data de hoje

        var availableDates = new GlideRecord('x_1593185_traini_0_training_schedule');
        // availableDates.addQuery('training_name', courseId);
        // availableDates.addQuery('training_date', '>', today); // Somente datas futuras

        availableDates.addEncodedQuery('training_name=' + courseId + '^training_date>javascript:gs.endOfToday()');
        availableDates.query();

        var allowedDates = [];
        while (availableDates.next()) {
            allowedDates.push(availableDates.getValue('sys_id'));
        }

        return 'sys_idIN' + allowedDates.join(',');
    },

    type: 'FutureCoursesFilter'
});
